cat > /workspace/csview_impl/src/main.rs << 'RUST_EOF'
use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader, IsTerminal, Write};
use std::process;

mod args;
mod csv_reader;
mod table;
mod unicode_width;

use args::{parse_args, Args, Align, Style};
use csv_reader::CsvReader;
use table::render_table;

fn main() {
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(2);
        }
    };

    let result = run(&args);
    match result {
        Ok(_) => {}
        Err(e) => {
            eprintln!("csview: {}", e);
            process::exit(1);
        }
    }
}

fn run(args: &Args) -> Result<(), String> {
    // Read CSV data
    let reader: Box<dyn BufRead> = match &args.file {
        Some(path) => {
            let f = File::open(path).map_err(|e| e.to_string())?;
            Box::new(BufReader::new(f))
        }
        None => Box::new(BufReader::new(io::stdin())),
    };

    let mut csv_reader = CsvReader::new(reader, args.delimiter, args.sniff_limit);
    let data = csv_reader.read_all()?;

    if data.is_empty() {
        // Single empty row
        let output = render_table(
            &[],
            &[],
            args,
        );
        output_result(&output, args.disable_pager);
        return Ok(());
    }

    let (headers, rows) = if args.no_headers {
        (None, data.as_slice())
    } else {
        (Some(&data[0]), &data[1..])
    };

    let num_col_num = if args.number { 1 } else { 0 };

    // Compute column widths
    let num_cols = if let Some(h) = headers {
        h.len()
    } else if !rows.is_empty() {
        rows[0].len()
    } else {
        0
    };
    let total_cols = num_cols + num_col_num;

    let output = render_table(
        headers.map(|h| h.as_slice()),
        rows,
        args,
    );

    output_result(&output, args.disable_pager);
    Ok(())
}

fn output_result(output: &str, disable_pager: bool) {
    let stdout = io::stdout();
    let is_tty = stdout.is_terminal();

    if is_tty && !disable_pager {
        // Use pager
        use_pager(output);
    } else {
        print!("{}", output);
    }
}

fn use_pager(content: &str) {
    // Try to use less or more as pager
    let pager = env::var("PAGER").unwrap_or_else(|_| "less".to_string());
    let pager_cmd = if pager.is_empty() { "less".to_string() } else { pager };

    let mut parts = pager_cmd.split_whitespace();
    let cmd = parts.next().unwrap_or("less");
    let extra_args: Vec<&str> = parts.collect();

    let result = std::process::Command::new(cmd)
        .args(&extra_args)
        .stdin(std::process::Stdio::piped())
        .spawn();

    match result {
        Ok(mut child) => {
            if let Some(stdin) = child.stdin.take() {
                let mut stdin = stdin;
                let _ = stdin.write_all(content.as_bytes());
            }
            let _ = child.wait();
        }
        Err(_) => {
            // Fall back to stdout
            print!("{}", content);
        }
    }
}
