use std::env;
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Style {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Align {
    Left,
    Center,
    Right,
}

#[derive(Debug)]
pub struct Args {
    pub file: Option<String>,
    pub no_headers: bool,
    pub number: bool,
    pub tsv: bool,
    pub delimiter: char,
    pub style: Style,
    pub padding: usize,
    pub indent: usize,
    pub sniff_limit: usize,
    pub header_align: Align,
    pub body_align: Align,
    pub disable_pager: bool,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            file: None,
            no_headers: false,
            number: false,
            tsv: false,
            delimiter: ',',
            style: Style::Sharp,
            padding: 1,
            indent: 0,
            sniff_limit: 1000,
            header_align: Align::Center,
            body_align: Align::Left,
            disable_pager: false,
        }
    }
}

pub struct ArgError(String);

impl fmt::Display for ArgError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

pub fn parse_args() -> Result<Args, ArgError> {
    let raw_args: Vec<String> = env::args().collect();
    let prog_name = raw_args.get(0).map(|s| s.as_str()).unwrap_or("csview");

    let mut args = Args::default();
    let mut i = 1;
    let argv = &raw_args[1..];
    let argc = argv.len();
    let mut pos_args: Vec<&str> = Vec::new();

    while i <= argc {
        if i == argc {
            break;
        }
        let arg = &argv[i - 1];
        i += 1;

        if arg == "--" {
            // All remaining are positional
            while i <= argc {
                pos_args.push(&argv[i - 1]);
                i += 1;
            }
            break;
        }

        if arg.starts_with("--") {
            let arg_str = &arg[2..];
            match arg_str {
                "no-headers" => {
                    args.no_headers = true;
                }
                "number" => {
                    args.number = true;
                }
                "tsv" => {
                    args.tsv = true;
                }
                "disable-pager" => {
                    args.disable_pager = true;
                }
                "help" => {
                    print_help();
                    std::process::exit(0);
                }
                "version" => {
                    println!("csview 1.3.4");
                    std::process::exit(0);
                }
                _ => {
                    // Handle --key=value or --key value
                    if let Some(eq_pos) = arg_str.find('=') {
                        let key = &arg_str[..eq_pos];
                        let val = &arg_str[eq_pos + 1..];
                        match key {
                            "delimiter" => {
                                args.delimiter = parse_char(val, "--delimiter <DELIMITER>")?;
                            }
                            "style" => {
                                args.style = parse_style(val)?;
                            }
                            "padding" => {
                                args.padding = parse_usize(val, "--padding <PADDING>")?;
                            }
                            "indent" => {
                                args.indent = parse_usize(val, "--indent <INDENT>")?;
                            }
                            "sniff" => {
                                args.sniff_limit = parse_usize(val, "--sniff <LIMIT>")?;
                            }
                            "header-align" => {
                                args.header_align = parse_align(val, "--header-align <HEADER_ALIGN>")?;
                            }
                            "body-align" => {
                                args.body_align = parse_align(val, "--body-align <BODY_ALIGN>")?;
                            }
                            _ => {
                                return Err(ArgError(format!(
                                    "error: unexpected argument '--{}' found\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.",
                                    key, prog_name
                                )));
                            }
                        }
                    } else {
                        // --key value (next arg)
                        match arg_str {
                            "delimiter" => {
                                let val = next_arg(argv, &mut i, argc, "--delimiter <DELIMITER>", prog_name)?;
                                args.delimiter = parse_char(val, "--delimiter <DELIMITER>")?;
                            }
                            "style" => {
                                let val = next_arg(argv, &mut i, argc, "--style <STYLE>", prog_name)?;
                                args.style = parse_style(val)?;
                            }
                            "padding" => {
                                let val = next_arg(argv, &mut i, argc, "--padding <PADDING>", prog_name)?;
                                args.padding = parse_usize(val, "--padding <PADDING>")?;
                            }
                            "indent" => {
                                let val = next_arg(argv, &mut i, argc, "--indent <INDENT>", prog_name)?;
                                args.indent = parse_usize(val, "--indent <INDENT>")?;
                            }
                            "sniff" => {
                                let val = next_arg(argv, &mut i, argc, "--sniff <LIMIT>", prog_name)?;
                                args.sniff_limit = parse_usize(val, "--sniff <LIMIT>")?;
                            }
                            "header-align" => {
                                let val = next_arg(argv, &mut i, argc, "--header-align <HEADER_ALIGN>", prog_name)?;
                                args.header_align = parse_align(val, "--header-align <HEADER_ALIGN>")?;
                            }
                            "body-align" => {
                                let val = next_arg(argv, &mut i, argc, "--body-align <BODY_ALIGN>", prog_name)?;
                                args.body_align = parse_align(val, "--body-align <BODY_ALIGN>")?;
                            }
                            _ => {
                                return Err(ArgError(format!(
                                    "error: unexpected argument '--{}' found\n\n  tip: to pass '--{}' as a value, use '-- --{}'\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.",
                                    arg_str, arg_str, arg_str, prog_name
                                )));
                            }
                        }
                    }
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            let flags = &arg[1..];
            let mut flag_iter = flags.chars().peekable();
            while let Some(flag) = flag_iter.next() {
                match flag {
                    'H' => args.no_headers = true,
                    'n' => args.number = true,
                    't' => args.tsv = true,
                    'P' => args.disable_pager = true,
                    'h' => {
                        print_help();
                        std::process::exit(0);
                    }
                    'V' => {
                        println!("csview 1.3.4");
                        std::process::exit(0);
                    }
                    'd' => {
                        // Rest of flag string is value, or next arg
                        let rest: String = flag_iter.collect();
                        let val = if rest.is_empty() {
                            let v = next_arg(argv, &mut i, argc, "--delimiter <DELIMITER>", prog_name)?;
                            v.to_string()
                        } else {
                            rest
                        };
                        args.delimiter = parse_char(&val, "--delimiter <DELIMITER>")?;
                        break;
                    }
                    's' => {
                        let rest: String = flag_iter.collect();
