// Unicode width calculation based on East Asian Width property
// Ambiguous (A), Wide (W), Fullwidth (F) = 2
// Narrow (Na), Neutral (N), Halfwidth (H) = 1
// Control characters = 0

pub fn char_width(c: char) -> usize {
    let cp = c as u32;

    // Control characters
    if cp < 0x20 || (cp >= 0x7f && cp < 0xa0) {
        return 0;
    }

    // ASCII range (except control chars already handled)
    if cp < 0x7f {
        return 1;
    }

    // Check wide/fullwidth/ambiguous
    if is_wide_or_ambiguous(cp) {
        2
    } else {
        1
    }
}

fn is_wide_or_ambiguous(cp: u32) -> bool {
    // Wide (W) characters
    // Halfwidth and Fullwidth Forms
    if cp >= 0xFF01 && cp <= 0xFF60 { return true; }  // Fullwidth
    if cp >= 0xFFE0 && cp <= 0xFFE6 { return true; }  // Fullwidth signs

    // CJK Unified Ideographs
    if cp >= 0x4E00 && cp <= 0x9FFF { return true; }
    if cp >= 0x3400 && cp <= 0x4DBF { return true; }  // CJK Extension A
    if cp >= 0x20000 && cp <= 0x2A6DF { return true; } // CJK Extension B
    if cp >= 0x2A700 && cp <= 0x2B73F { return true; } // CJK Extension C
    if cp >= 0x2B740 && cp <= 0x2B81F { return true; } // CJK Extension D
    if cp >= 0x2B820 && cp <= 0x2CEAF { return true; } // CJK Extension E
    if cp >= 0x2CEB0 && cp <= 0x2EBEF { return true; } // CJK Extension F
    if cp >= 0xF900 && cp <= 0xFAFF { return true; }   // CJK Compatibility Ideographs
    if cp >= 0x2F800 && cp <= 0x2FA1F { return true; } // CJK Compatibility Supplement

    // CJK Compatibility
    if cp >= 0x3300 && cp <= 0x33FF { return true; }
    if cp >= 0xFE30 && cp <= 0xFE4F { return true; }

    // Japanese
    if cp >= 0x3040 && cp <= 0x309F { return true; }  // Hiragana
    if cp >= 0x30A0 && cp <= 0x30FF { return true; }  // Katakana
    if cp >= 0x31F0 && cp <= 0x31FF { return true; }  // Katakana Phonetic Extensions
    if cp >= 0xFF65 && cp <= 0xFF9F { return true; }  // Halfwidth Katakana - wait these are halfwidth

    // Korean
    if cp >= 0xAC00 && cp <= 0xD7AF { return true; }  // Hangul syllables
    if cp >= 0x1100 && cp <= 0x11FF { return true; }  // Hangul Jamo
    if cp >= 0xA960 && cp <= 0xA97F { return true; }  // Hangul Jamo Extended-A
    if cp >= 0xD7B0 && cp <= 0xD7FF { return true; }  // Hangul Jamo Extended-B
    if cp >= 0x3130 && cp <= 0x318F { return true; }  // Hangul Compatibility Jamo

    // Bopomofo
    if cp >= 0x02EA && cp <= 0x02EB { return true; }
    if cp >= 0x3100 && cp <= 0x312F { return true; }
    if cp >= 0x31A0 && cp <= 0x31BF { return true; }

    // CJK symbols and punctuation
    if cp >= 0x3000 && cp <= 0x303F { return true; }

    // Enclosed CJK
    if cp >= 0x3200 && cp <= 0x32FF { return true; }

    // Wide characters range
    if cp >= 0xFE10 && cp <= 0xFE1F { return true; }  // Vertical Forms
    if cp >= 0xFE50 && cp <= 0xFE6F { return true; }  // Small Forms

    // Yi
    if cp >= 0xA000 && cp <= 0xA4CF { return true; }

    // Emoji and symbols (most are wide)
    if cp >= 0x1F300 && cp <= 0x1F9FF { return true; }  // Misc symbols and pictographs
    if cp >= 0x1FA00 && cp <= 0x1FAFF { return true; }  // Symbols Extended-A

    // Ambiguous characters (treated as wide = 2)
    is_ambiguous(cp)
