use std::io::BufRead;

pub struct CsvReader<R: BufRead> {
    reader: R,
    delimiter: char,
    sniff_limit: usize,
}

impl<R: BufRead> CsvReader<R> {
    pub fn new(reader: R, delimiter: char, sniff_limit: usize) -> Self {
        CsvReader {
            reader,
            delimiter,
            sniff_limit,
        }
    }

