                    }
                } else {
                    in_quotes = true;
                }
            }
            Some(c) if c == delimiter && !in_quotes => {
                fields.push(field);
                field = String::new();
            }
            Some(c) => {
                field.push(c);
            }
        }
    }

    Ok((fields, bytes))
}

