impl<R: BufRead> CsvReader<R> {
    pub fn new(reader: R, delimiter: char, sniff_limit: usize) -> Self {
        CsvReader {
            reader,
            delimiter,
            sniff_limit,
        }
    }

    pub fn read_all(&mut self) -> Result<Vec<Vec<String>>, String> {
        let mut records: Vec<Vec<String>> = Vec::new();
        let mut line_num = 0u64;
        let mut byte_offset = 0u64;
        let mut expected_fields: Option<usize> = None;
        let mut record_num = 0u64;

        loop {
            let mut line = String::new();
            let bytes_read = self.reader.read_line(&mut line)
                .map_err(|e| format!("IO error: {}", e))?;

            if bytes_read == 0 {
                break; // EOF
            }

            line_num += 1;

            // Parse the CSV line(s) - may span multiple lines due to quoted fields
            let record_start_byte = byte_offset;
            let record_start_line = line_num;

            // We need to handle multi-line quoted fields
            let (record, total_bytes) = self.parse_record(&line, &mut line_num, &mut byte_offset)?;
            byte_offset += bytes_read as u64;

            // Skip empty records
            if record.len() == 1 && record[0].is_empty() {
                continue;
            }

            // Check field count consistency
            match expected_fields {
                None => {
                    expected_fields = Some(record.len());
                }
                Some(expected) => {
                    if record.len() != expected {
                        return Err(format!(
                            "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                            record_num, record_start_line, record_start_byte, record.len(), expected
                        ));
                    }
                }
            }

            records.push(record);
            record_num += 1;
        }

        Ok(records)
    }

    fn parse_record(&self, first_line: &str, _line_num: &mut u64, _byte_offset: &mut u64) -> Result<(Vec<String>, usize), String> {
        // Simple single-line parse for now - we'll handle multi-line in read_all
        parse_csv_line(first_line, self.delimiter)
    }
}

fn parse_csv_line(line: &str, delimiter: char) -> Result<(Vec<String>, usize), String> {
    let mut fields: Vec<String> = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();
    let bytes = line.len();

    // Remove trailing newline
    let line = line.trim_end_matches('\n').trim_end_matches('\r');
    let mut chars = line.chars().peekable();

    loop {
        match chars.next() {
            None => {
                fields.push(field);
                break;
            }
            Some(c) if c == '"' => {
                if in_quotes {
                    // Check for escaped quote
                    if chars.peek() == Some(&'"') {
                        chars.next();
                        field.push('"');
                    } else {
                        in_quotes = false;
                    }
                } else {
                    in_quotes = true;
                }
            }
            Some(c) if c == delimiter && !in_quotes => {
                fields.push(field);
                field = String::new();
            }
            Some(c) => {
                field.push(c);
            }
        }
    }

    Ok((fields, bytes))
}

