            } else {
                &line
            };

            let mut chars = trimmed.chars().peekable();

            loop {
                match chars.next() {
                    None => {
                        if !eol {
                            // EOF without newline
                            fields.push(field);
                            return Ok(Some(fields));
                        }
                        if in_quotes {
                            // Multi-line quoted field
                            field.push('\n');
                            break; // Read next line
                        } else {
                            // End of record
                            fields.push(field);
                            return Ok(Some(fields));
                        }
                    }
                    Some(c) if c == '"' => {
                        if in_quotes {
                            if chars.peek() == Some(&'"') {
                                chars.next();
                                field.push('"');
                            } else {
                                in_quotes = false;
                            }
                        } else {
                            in_quotes = true;
                        }
                    }
