use crate::args::{Args, Style, Align};
use crate::unicode_width::{str_display_width, char_width, truncate_str};

pub fn render_table(
    headers: Option<&[String]>,
    rows: &[Vec<String>],
    args: &Args,
) -> String {
    let padding = args.padding;
    let indent = args.indent;
    let number_lines = args.number;
    let sniff_limit = args.sniff_limit;

    // Determine number of columns
    let data_cols = if let Some(h) = headers {
        h.len()
    } else if !rows.is_empty() {
        rows[0].len()
    } else {
        0
    };

    let num_col = if number_lines { 1 } else { 0 };
    let total_cols = data_cols + num_col;

    if total_cols == 0 {
        // Empty table
        return render_empty_table(args, indent);
    }

    // Compute column widths
    // First, collect all string data
    let num_rows = rows.len();

    // Calculate the max number to display (for row number column width)
    let max_row_num = num_rows;
    let row_num_width = if number_lines {
        let s = max_row_num.max(1).to_string();
        s.len().max(str_display_width("#"))
    } else {
        0
    };

    // Initialize col_widths
    let mut col_widths: Vec<usize> = vec![0; total_cols];

    if number_lines {
        col_widths[0] = row_num_width;
    }

    // Set header widths
    if let Some(h) = headers {
        for (ci, cell) in h.iter().enumerate() {
            let ci_total = ci + num_col;
            let w = str_display_width(cell);
            if w > col_widths[ci_total] {
                col_widths[ci_total] = w;
            }
        }
    }

    // Set data widths, limited by sniff_limit
    let sniff_rows = if sniff_limit == 0 { rows.len() } else { sniff_limit.min(rows.len()) };

    for ri in 0..sniff_rows {
        if ri >= rows.len() { break; }
        let row = &rows[ri];
        for (ci, cell) in row.iter().enumerate() {
            let ci_total = ci + num_col;
            if ci_total >= total_cols { break; }
            let w = str_display_width(cell);
            if w > col_widths[ci_total] {
                col_widths[ci_total] = w;
            }
        }
    }

    // Build the table output
    let mut output = String::new();

    match &args.style {
        Style::Sharp => render_sharp(&mut output, headers, rows, &col_widths, args, indent, false, false),
        Style::Rounded => render_sharp(&mut output, headers, rows, &col_widths, args, indent, true, false),
        Style::Reinforced => render_sharp(&mut output, headers, rows, &col_widths, args, indent, false, true),
        Style::Ascii => render_ascii(&mut output, headers, rows, &col_widths, args, indent),
        Style::Ascii2 => render_ascii2(&mut output, headers, rows, &col_widths, args, indent),
        Style::None => render_none(&mut output, headers, rows, &col_widths, args, indent),
        Style::Markdown => render_markdown(&mut output, headers, rows, &col_widths, args, indent),
        Style::Grid => render_sharp(&mut output, headers, rows, &col_widths, args, indent, false, false),
    }

    if let Style::Grid = &args.style {
        // Grid style adds separators between each row - already handled
    }

    output
}

fn render_empty_table(args: &Args, indent: usize) -> String {
    // Single empty row (from empty CSV input)
    let prefix = " ".repeat(indent);
    match &args.style {
        Style::Sharp => {
            format!("{}┌┐\n{}│ │\n{}└┘\n", 
                prefix, prefix, prefix)
        }
        Style::Rounded => {
            format!("{}╭╮\n{}│ │\n{}╰╯\n",
                prefix, prefix, prefix)
        }
        Style::Reinforced => {
            format!("{}┏┓\n{}│ │\n{}┗┛\n",
                prefix, prefix, prefix)
        }
        Style::Ascii => {
            format!("{}++\n{}| |\n{}++\n",
                prefix, prefix, prefix)
        }
        Style::Ascii2 => {
            format!("{} \n{} \n",
                prefix, prefix)
        }
        Style::None => {
            format!("{} \n{} \n",
                prefix, prefix)
        }
        Style::Markdown => {
            format!("{}| |\n{}|---|\n{}| |\n",
                prefix, prefix, prefix)
        }
        Style::Grid => {
            format!("{}┌┐\n{}│ │\n{}└┘\n",
                prefix, prefix, prefix)
        }
    }
}

fn format_cell(content: &str, col_width: usize, align: &Align, max_width: usize) -> String {
    // Truncate to max_width if needed
    let content = truncate_str(content, max_width);
    let actual_width = str_display_width(content);

    let pad = if col_width > actual_width { col_width - actual_width } else { 0 };

    match align {
        Align::Left => {
            let mut s = content.to_string();
            for _ in 0..pad { s.push(' '); }
            s
        }
        Align::Right => {
            let mut s = String::new();
            for _ in 0..pad { s.push(' '); }
            s.push_str(content);
            s
        }
        Align::Center => {
            let left_pad = pad / 2;
            let right_pad = pad - left_pad;
            let mut s = String::new();
            for _ in 0..left_pad { s.push(' '); }
            s.push_str(content);
            for _ in 0..right_pad { s.push(' '); }
            s
        }
    }
}

fn render_sharp(
