        output.push('\n');
    }

    // Data rows
    for (ri, row) in rows.iter().enumerate() {
        // Grid separator between data rows (not before first row if no header, and not after last)
        if is_grid && ri > 0 {
            output.push_str(&prefix);
            output.push_str(ml);
            for (ci, &cw) in col_widths.iter().enumerate() {
                let width = cw + 2 * padding;
                for _ in 0..width { output.push_str(h); }
                if ci < total_cols - 1 {
