new_content = '''use std::io::BufRead;

// More complete CSV reader that handles multi-line fields
pub struct FullCsvReader<R: BufRead> {
    reader: R,
    delimiter: char,
    sniff_limit: usize,
    byte_offset: u64,
    line_num: u64,
    record_num: u64,
}

impl<R: BufRead> FullCsvReader<R> {
    pub fn new(reader: R, delimiter: char, sniff_limit: usize) -> Self {
        FullCsvReader {
            reader,
            delimiter,
            sniff_limit,
            byte_offset: 0,
            line_num: 0,
            record_num: 0,
        }
    }

    pub fn read_all(&mut self) -> Result<Vec<Vec<String>>, String> {
        let mut records: Vec<Vec<String>> = Vec::new();
        let mut expected_fields: Option<usize> = None;

        loop {
            let record_start_byte = self.byte_offset;
            let record_start_line = self.line_num + 1;

            let record = match self.read_record()? {
                None => break,
                Some(r) => r,
            };

            // Skip empty records (single empty field = empty line)
            if record.len() == 1 && record[0].is_empty() {
                continue;
            }

            match expected_fields {
                None => {
                    expected_fields = Some(record.len());
                }
                Some(expected) => {
                    if record.len() != expected {
                        return Err(format!(
                            "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                            self.record_num, record_start_line, record_start_byte, record.len(), expected
                        ));
                    }
                }
            }

            records.push(record);
            self.record_num += 1;
        }

        Ok(records)
    }

    fn read_record(&mut self) -> Result<Option<Vec<String>>, String> {
        let mut fields: Vec<String> = Vec::new();
        let mut field = String::new();
        let mut in_quotes = false;
        let mut started = false;

        loop {
            let mut line = String::new();
            let bytes_read = self.reader.read_line(&mut line)
                .map_err(|e| format!("IO error: {}", e))?;

            if bytes_read == 0 {
                if started {
                    fields.push(field);
                    return Ok(Some(fields));
                }
                return Ok(None);
            }

            started = true;
            self.byte_offset += bytes_read as u64;
            self.line_num += 1;

            // Remove \\r\\n or \\n at end
            let eol = line.ends_with(\'\\n\');
            let trimmed = if line.ends_with("\\r\\n") {
                &line[..line.len() - 2]
            } else if line.ends_with(\'\\n\') {
                &line[..line.len() - 1]
            } else {
                &line
            };

            let mut chars = trimmed.chars().peekable();

            loop {
                match chars.next() {
                    None => {
                        if !eol {
                            // EOF without newline
                            fields.push(field);
                            return Ok(Some(fields));
                        }
                        if in_quotes {
                            // Multi-line quoted field
                            field.push(\'\\n\');
                            break; // Read next line
                        } else {
                            // End of record
                            fields.push(field);
                            return Ok(Some(fields));
                        }
                    }
                    Some(c) if c == \'"\'  => {
                        if in_quotes {
                            if chars.peek() == Some(&\'"\'  ) {
                                chars.next();
                                field.push(\'"\'  );
                            } else {
                                in_quotes = false;
                            }
                        } else {
                            in_quotes = true;
                        }
                    }
                    Some(c) if c == self.delimiter && !in_quotes => {
                        fields.push(field);
                        field = String::new();
                    }
                    Some(c) => {
                        field.push(c);
                    }
                }
            }
        }
    }
}
'''

with open('/workspace/csview_impl/src/csv_reader.rs', 'w') as f:
    f.write(new_content)
print("Cleaned up csv_reader.rs")
PYEOF

